        @Test func tiesToEvenAndBudgetBoundary() throws {
            let g = try NemotronSuperImagePreprocessing.grid(width: 32, height: 16,
                downsampleFactor: 1, minimumPatches: 1, maximumPatches: 100)
            #expect(g.widthPatches == 2 && g.heightPatches == 2)
            let minimum = try NemotronSuperImagePreprocessing.grid(width: 16, height: 16,
                maximumPatches: 1024)
            // The upstream rule only upscales if available > minimum, not >=.
            #expect(minimum.widthPatches == 2 && minimum.heightPatches == 2)
        }
        @Test func rejectsAllocationAbuseBeforeBuffers() {
            // A valid single RGB pixel ensures rejection comes from admission,
            // not a pixel-count mismatch. These calls must never allocate targets.
            for (w, h) in [(67108864, 1), (1, 67108864), (6144, 4096)] {
                #expect(throws: NemotronSuperImagePreprocessing.Failure.workspaceLimit) {
                    try NemotronSuperImagePreprocessing.normalizeRGB([0, 0, 0],
                        width: 1, height: 1, targetWidth: w, targetHeight: h)
                }
            }
        }
        @Test func admitsDefaultMaximumPatchGridsWithoutAllocating() throws {
            // 13312 patches * 16 * 16 pixels, square-ish and extreme default grids.
            for (w, h) in [(2048, 1664), (106496, 32), (32, 106496)] {
                try NemotronSuperImagePreprocessing.validateWorkspace(width: w, height: h,
                    targetWidth: w, targetHeight: h)
            }
        }
        @Test func rejectsInvalidShapes() {
            for (w, h) in [(0, 2), (-1, 2), (Int.max, 2), (1, 64 * 1024 * 1024)] {
                #expect(throws: (any Error).self) {
                    try NemotronSuperImagePreprocessing.grid(width: w, height: h)
                }
            }
            #expect(throws: (any Error).self) {
                try NemotronSuperImagePreprocessing.normalizeRGB([0], width: 1, height: 1,
                    targetWidth: 1, targetHeight: 1)
            }
            #expect(throws: (any Error).self) {
                try NemotronSuperImagePreprocessing.grid(width: 16, height: 16, imageCount: 0)
            }
        }
